<script setup lang="ts">import{onMounted,ref}from'vue';import{users,updateUser,setRole}from'../api/auth';import{ElMessage,ElMessageBox}from'element-plus';import PageHeader from'../components/PageHeader.vue';const rows=ref<any[]>([]);async function load(){const r:any=await users();rows.value=Array.isArray(r.data)?r.data:[]}async function toggle(u:any){await updateUser(u.username,{enabled:!u.enabled});ElMessage.success('账号状态已更新');load()}async function role(u:any){const value=await ElMessageBox.prompt('输入角色：GUEST / USER / ADMIN','修改角色',{inputValue:u.role});await setRole(u.username,value.value.toUpperCase());ElMessage.success('角色已更新');load()}onMounted(load)</script>
<template><PageHeader title="用户管理" description="管理账号状态与访问角色"><button class="btn secondary" @click="load">↻ 刷新</button></PageHeader><div class="card table-wrap"><table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="u in rows" :key="u.username"><td class="path-cell">{{u.username}}</td><td><span class="type-pill">{{u.role}}</span></td><td>{{u.enabled?'启用':'禁用'}}</td><td>{{u.lastLoginAt||'—'}}</td><td><button class="btn secondary" @click="toggle(u)">{{u.enabled?'禁用':'启用'}}</button> <button class="btn secondary" @click="role(u)">修改角色</button></td></tr><tr v-if="!rows.length"><td colspan="5" class="empty">暂无用户</td></tr></tbody></table></div></template>
